question.answer:
package main

import "strings"

// blend is one recipe on the detox board.
type blend struct {
	name  string
	sugar int
}

// clean returns the slug of every blend under the sugar limit, in board order.
func clean(board []blend, limit int) []string {
	var slugs []string
	for _, b := range board {
		if b.sugar < limit {
			slugs = append(slugs, strings.ReplaceAll(strings.ToLower(b.name), " ", "-"))
		}
	}
	return slugs
}

// halve halves the sugar of every blend on the board.
func halve(board []blend) {
	for i := range board {
		board[i].sugar /= 2
	}
}

