question.answer:
package main

import "iter"

// countdown returns an iterator over n down to 1.
func countdown(n int) iter.Seq[int] {
	return func(yield func(int) bool) {
		for i := n; i > 0; i-- {
			if !yield(i) {
				return
			}
		}
	}
}

// firstUnder returns the first value under floor, or 0 when there is none.
func firstUnder(seq iter.Seq[int], floor int) int {
	for v := range seq {
		if v < floor {
			return v
		}
	}
	return 0
}

testcode.text:
seen := 0
for v := range countdown(5) {
	seen++
	if v == 3 {
		break
	}
}
fmt.Println(seen)

fmt.Println(firstUnder(countdown(0), 5), firstUnder(countdown(4), 1))
for range countdown(0) {
	fmt.Println("the field is not empty")
}
fmt.Println("last one out")

handed := 0
counted := func(yield func(int) bool) {
	for v := range countdown(5) {
		handed++
		if !yield(v) {
			return
		}
	}
}
fmt.Println(firstUnder(counted, 3), handed)

