question.answer:
package main

import (
	"iter"
	"maps"
	"slices"
)

// bin holds the lost property office's count of every item handed in.
type bin struct {
	counts map[string]int
}

// newBin returns an empty bin.
func newBin() *bin {
	return &bin{counts: map[string]int{}}
}

// hand records one more of item.
func (b *bin) hand(item string) {
	b.counts[item]++
}

// labels returns every recorded label in ascending order.
func (b *bin) labels() []string {
	labels := slices.Collect(maps.Keys(b.counts))
	slices.Sort(labels)
	return labels
}

// total returns how many items the bin holds in all.
func (b *bin) total() int {
	sum := 0
	for _, n := range b.counts {
		sum += n
	}
	return sum
}

// over yields every label recorded more than n times, in ascending order.
func (b *bin) over(n int) iter.Seq[string] {
	return func(yield func(string) bool) {
		for _, label := range b.labels() {
			if b.counts[label] <= n {
				continue
			}
			if !yield(label) {
				return
			}
		}
	}
}

testcode.text:
b := newBin()
fmt.Println(b.labels() == nil, b.total(), len(b.labels()))
for range b.over(0) {
	fmt.Println("the bin is not empty")
}
fmt.Println("bin empty")

b := newBin()
for _, item := range []string{"whistle", "boot", "anorak", "scarf", "kite", "boot", "kite", "kite"} {
	b.hand(item)
}
fmt.Println(b.labels(), b.total())
seen := 0
for label := range b.over(0) {
	seen++
	fmt.Println(label)
	if label == "boot" {
		break
	}
}
fmt.Println(seen)

