// hire is one costume on the price list.
type hire struct {
	costume string
	cost    int
}

// affordable returns the name of every costume within budget, in ascending order.
func affordable(list []hire, budget int) []string {
	kept := slices.Clone(list)
	kept = slices.DeleteFunc(kept, func(h hire) bool { return h.cost > budget })
	names := make([]string, len(kept))
	for i, h := range kept {
		names[i] = h.costume
	}
	slices.Sort(names)
	return names
}

// spend returns the total cost of every costume within budget.
func spend(list []hire, budget int) int {
	kept := slices.Clone(list)
	kept = slices.DeleteFunc(kept, func(h hire) bool { return h.cost > budget })
	sum := 0
	for _, h := range kept {
		sum += h.cost
	}
	return sum
}

question.answer:
package main

import "slices"

// hire is one costume on the price list.
type hire struct {
	costume string
	cost    int
}

// affordable returns the name of every costume within budget, in ascending order.
func affordable(list []hire, budget int) []string {
	var names []string
	for _, h := range list {
		if h.cost <= budget {
			names = append(names, h.costume)
		}
	}
	slices.Sort(names)
	return names
}

// spend returns the total cost of every costume within budget.
func spend(list []hire, budget int) int {
	sum := 0
	for _, h := range list {
		if h.cost <= budget {
			sum += h.cost
		}
	}
	return sum
}

testcode.text:
fmt.Println(affordable(nil, 10), spend(nil, 10))
list := []hire{{"wig", 5}, {"wig", 5}, {"cape", 20}}
fmt.Println(affordable(list, 5), spend(list, 5), affordable(list, 4))
